pd.DataFrame(schema,columns=['table_name','observed_schema_fields','semantic','archived_bounded_evidence','archived_coverage','phase1_status','limitations']).to_csv(OUT/'table_schema_and_timestamp_audit.csv',index=False)
tables=['keyboard','applications_foreground','screen','touch','plugin_google_activity_recognition','sensor_accelerometer','sensor_linear_accelerometer','sensor_gyroscope','sensor_gravity','sensor_rotation']
frames={}
for t in tables:
 p=COV/t/f'{t}_phase2a_t1_ranked_coverage_scan.csv'
 if p.exists():
  d=pd.read_csv(p,dtype={'Subject_ID_D':str}); d['n_rows']=pd.to_numeric(d['n_rows'],errors='coerce').fillna(0)
  frames[t]=d.groupby(['Subject_ID_D','window_start_ms','window_end_ms'],as_index=False).agg(n_rows=('n_rows','sum'),devices=('device_id','nunique'))
rows=[]
for i,a in enumerate(tables):
 for b in tables[i+1:]:
  if a not in frames or b not in frames: continue
  x=frames[a].rename(columns={'n_rows':'a_rows','devices':'a_devices'}); y=frames[b].rename(columns={'n_rows':'b_rows','devices':'b_devices'})
  j=x.merge(y,on=['Subject_ID_D','window_start_ms','window_end_ms'],how='outer').fillna(0); both=j[(j.a_rows>0)&(j.b_rows>0)]
  rows.append({'table_a':a,'table_b':b,'coverage_scope':'Phase 2A selected review windows only (not all patients)','patients_with_any_archived_window_a':int(x.loc[x.a_rows>0,'Subject_ID_D'].nunique()),'patients_with_any_archived_window_b':int(y.loc[y.b_rows>0,'Subject_ID_D'].nunique()),'patient_windows_both_nonzero':len(both),'patients_both_nonzero':both.Subject_ID_D.nunique(),'timestamp_level_overlap':'not_estimable from archived window counts','note':'Same patient and same primary/fallback window only; not proof of simultaneous events.'})
pd.DataFrame(rows).to_csv(OUT/'patient_temporal_overlap_matrix.csv',index=False)
short=[]
for t in ['keyboard','screen','touch','applications_foreground','plugin_google_activity_recognition','accelerometer','linear_accelerometer','gyroscope','gravity','rotation']:
 short.append({'feature_window':f'{t} × keyboard/app context; 1,5,10,15 min','table_or_pair':t,'patients_with_timestamp_level_overlap':np.nan,'episodes':np.nan,'patient_days':np.nan,'patients':np.nan,'status':'not computed','reason':'Archived outputs contain bounded window counts, not event-level rows; live SensorDB host unavailable during audit.','recommended_next_step':'Run bounded same-device event query before implementation.'})
pd.DataFrame(short).to_csv(OUT/'short_window_feasibility.csv',index=False)
proposals=[
 ('acc_motion_variability_during_keyboard','accelerometer + keyboard','1–5 min; same device; keyboard observations define episode; ACC samples within episode','partial','pilot ACC dense (~10.7 Hz) but no all-patient synchronized counts','raw accelerometer magnitude variability after gravity handling; not typing-specific movement','pilot first','literature-supported by Ning et al.; approximate only'),
 ('acc_jerk_during_foreground_app','accelerometer + applications_foreground','1–5 min around foreground package episode','partial','ACC raw bounded query and irregular-sampling QC required','jerk of resampled dynamic magnitude; raw or gravity-compensated must be explicit','pilot first','inspired by sensor-fusion literature; novel in this schema'),
 ('motion_around_keyboard_correction','accelerometer + keyboard','±5 s around aggregate correction-like transition','unavailable','keyboard correction proxy exists; ACC event-level overlap not archived','motion change around text-state deletion; exploratory and privacy-safe','defer','novel hypothesis'),
 ('motion_around_screen_activation','accelerometer + screen','±5/30/60 s around unlock/on event','partial','screen events available; ACC timestamp overlap not quantified','phone-motion context around screen activation','pilot first','literature-supported context measure; not tremor/gait'),
 ('screen_touch_burst_variability','screen + touch','1–5 min unlocked sessions','available for aggregate pilot','both tables have bounded T1 windows, but timestamp-level all-patient overlap not archived','touch-event burst count/dispersion during unlocked sessions','pilot first','strong technical feasibility; novel outcome use'),
 ('foreground_app_switching_during_screen_sessions','applications_foreground + screen','screen-unlocked sessions; 1–15 min','available for aggregate pilot','both event tables have bounded windows; exact co-timestamps require live query','switch count/entropy per unlocked minute','implement now after bounded query','supported by passive sensing literature'),
 ('app_specific_snapshot_typing_variability','keyboard + applications_foreground','same package; 1–5 min bursts','available for aggregate pilot','keyboard/app coverage strong; exact same-event pairing not archived','snapshot IEI summaries stratified by package, not key speed','implement now after deduplication','supported approximately'),
 ('stationary_vs_moving_phone_usage','accelerometer/activity recognition + keyboard/screen','1–15 min episodes','partial','activity-recognition pilot rows exist; ACC all-patient overlap unavailable','keyboard/screen activity during classifier stationary/active context','pilot first','literature-supported context; no clinical motor label'),
]
pd.DataFrame(proposals,columns=['feature','required_tables','matching_rule','availability','coverage_evidence','definition_and_interpretation','recommendation','evidence_class']).to_csv(OUT/'cross_modal_feature_proposals.csv',index=False)
readme='''# Cross-Table Digital Phenotyping — Phase 1\n\n## Scope\nThis phase audited saved SensorDB schema reviews and bounded T1 coverage outputs. It did not train models, run cognition screens, or join massive raw motion tables. The live SensorDB host was unavailable during this run (`Unknown MySQL server host`), so timestamp-level ±5/30/60-second overlap counts were not claimed from archived window-count tables.\n\n## Literature\nThe literature register verifies Ning et al. (CHI 2023, PMID 38115842), Twose et al. (Alzheimer’s & Dementia, DOI 10.1002/alz.086452), the older-adult multimodal guide (Innovation in Aging, PMID 41853224 / DOI 10.1093/geroni/igag007), Butler et al. (Nature Medicine 2025, DOI 10.1038/s41591-024-03475-9), and DeepMood as a directly relevant supplementary source. Literature supports synchronizing keyboard dynamics with accelerometer context and using daily/session summaries, but the closest studies use true keypress events or proprietary sensor streams.\n\n## Local data audit\nKeyboard, applications_foreground, screen and touch have usable bounded T1 examples. Keyboard has 80 mapped patients and 3,150,391 mapped rows; applications_foreground has 86 patients and 2,020,313 rows. A selected patient/device 24-hour window contained 1,832 keyboard rows, 698 foreground-app rows, 304 screen rows, 1,820 touch rows and 423 activity-recognition rows. Archived accelerometer pilot data demonstrated dense raw signal (~3,202 rows in five minutes, approximately 10.7 Hz), but broad patient-level raw motion overlap was not available. Linear accelerometer had no rows in the checked T1-week protocol windows; gyroscope, gravity and rotation likewise had zero rows in the reviewed primary windows.\n\n## Synchronization decision\nThe archived coverage scans include only the Phase 2A selected review windows and support same-patient/same-window co-coverage for that pilot record only. They do not contain enough event-level rows to calculate true simultaneous overlap or ±5/30/60-second coverage. Those deliverables are explicitly marked `not computed` in `short_window_feasibility.csv`, rather than treating calendar-window co-coverage as synchronization.\n\n## Priority\nThe first pilot should use screen–touch burst variability or foreground-app switching during screen-unlocked sessions because both are event-based and technically accessible. A second pilot can add keyboard snapshot variability stratified by application. Accelerometer-coupled features should wait for a bounded same-device raw-motion query and sampling/duplicate QC. Jerk must be defined on resampled, gravity-compensated or explicitly raw acceleration; no feature should be called tremor, gait, or hand-motor impairment.\n\n## Files\n- `literature_to_feature_matrix.csv`\n- `table_schema_and_timestamp_audit.csv`\n- `patient_temporal_overlap_matrix.csv`\n- `short_window_feasibility.csv`\n- `cross_modal_feature_proposals.csv`\n\nAll historical keyboard, sensor and model outputs are preserved.\n'''
(OUT/'README_cross_modal_phase1.md').write_text(readme)
print('wrote',OUT)
